# len() of an element is not a read of its field named length.
from array import array as _vsc_array
# Generated by Viscosity: bounds check matching list's IndexError.
def _vsc_ix(c, i):
    if -c.n <= i < c.n:
        return i
    raise IndexError('list index out of range')
# Generated by Viscosity: like iterating a list, re-checks the length each step.
def _vsc_iter(c):
    i = 0
    while i < c.n:
        yield i
        i += 1
# Generated by Viscosity: "gs" stored as a struct of arrays (fields length).
class _Vsc_gs:
    __slots__ = ('n', 'length')
    def __init__(self):
        self.n = 0
        self.length = _vsc_array('d')
    def append(self, v0):
        self.length.append(v0)
        self.n += 1
    def __len__(self):
        return self.n
    @classmethod
    def _of(cls, *v):
        c = cls()
        for i in range(0, len(v), 1):
            c.append(v[i + 0])
        return c

from dataclasses import dataclass

